pub fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    assert!(!sep.is_empty(), "separator must be non-empty");

    a.into_iter()
        .map(|s| {
            if maxsplit == 0 {
                return vec![s];
            }
            if s.is_empty() {
                return vec![String::new()];
            }

            // rsplitn splits from the right; it yields at most n parts.
            // n = maxsplit + 1 parts max.
            let n = (maxsplit as usize) + 1;
            let mut parts: Vec<String> = s.rsplitn(n, &sep).map(|p| p.to_string()).collect();
            parts.reverse(); // restore left-to-right order
            parts
        })
        .collect()
}